/**
 * Mausam service worker.
 *
 * Provides three things the app previously had none of:
 *   1. An offline shell, so losing connectivity shows the last real forecast
 *      plus an honest "offline" banner instead of a dead page.
 *   2. Runtime caching of the weather APIs, so a reload on a flaky train
 *      connection still renders something true.
 *   3. Web Push delivery for P0 severe warnings (`warnings_override`), which
 *        until now could only be seen by opening the app.
 *
 * Deliberately hand-written rather than generated by Workbox: the caching rules
 * here are few and specific, and a build-step-free file is one less thing that
 * can silently stop matching the app it caches.
 *
 * Bump CACHE_VERSION to invalidate every cache on the next deploy.
 */

const CACHE_VERSION = "v1";
const SHELL_CACHE = `mausam-shell-${CACHE_VERSION}`;
const STATIC_CACHE = `mausam-static-${CACHE_VERSION}`;
const DATA_CACHE = `mausam-data-${CACHE_VERSION}`;

const OFFLINE_URL = "/offline.html";

/**
 * Only the truly static, always-present files. App routes are *not* precached:
 * Next.js serves them with hashed asset references, so a precached HTML shell
 * goes stale the moment you deploy. They are cached on first visit instead.
 */
const SHELL_ASSETS = [OFFLINE_URL, "/manifest.json", "/logo.png", "/icon-192x192.png"];

/** Cross-origin data APIs worth keeping a last-known copy of. */
const DATA_ORIGINS = [
  "https://api.open-meteo.com",
  "https://air-quality-api.open-meteo.com",
  "https://nominatim.openstreetmap.org",
  "https://api.rainviewer.com",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // addAll() rejects the whole batch if any single request 404s, which would
      // leave the SW uninstalled. Add individually and tolerate misses.
      await Promise.all(
        SHELL_ASSETS.map((url) => cache.add(new Request(url, { cache: "reload" })).catch(() => {}))
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([SHELL_CACHE, STATIC_CACHE, DATA_CACHE]);
      const names = await caches.keys();
      await Promise.all(names.filter((n) => !keep.has(n)).map((n) => caches.delete(n)));
      await self.clients.claim();
    })()
  );
});

/** Immutable, content-hashed build output — safe to serve from cache forever. */
function isImmutableAsset(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/map-imgs/") ||
    /\.(?:png|jpg|jpeg|svg|webp|ico|woff2?)$/.test(url.pathname)
  );
}

function isDataRequest(url) {
  if (DATA_ORIGINS.includes(url.origin)) return true;
  // Same-origin API routes: weather tiles, chat, persona insights.
  return url.origin === self.location.origin && url.pathname.startsWith("/api/");
}

/** The FastAPI backend. Cached so an offline homepage has real content. */
function isBackendRequest(url) {
  return (
    url.pathname === "/homepage" ||
    url.pathname === "/explain" ||
    url.pathname === "/preferences" ||
    url.pathname === "/insights"
  );
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response && response.ok) cache.put(request, response.clone());
  return response;
}

/**
 * Network-first with a cache fallback, and a timestamp so the app can tell how
 * old a fallback is. The stored `sw-cached-at` header is what surfaces in the UI
 * as "showing last update from …".
 */
async function networkFirstWithTimestamp(request, cacheName) {
  const cache = await caches.open(cacheName);

  try {
    const response = await fetch(request);
    if (response && response.ok) {
      // Response headers are immutable, so rebuild it to stamp the fetch time.
      const body = await response.clone().blob();
      const headers = new Headers(response.headers);
      headers.set("sw-cached-at", new Date().toISOString());
      cache.put(
        request,
        new Response(body, { status: response.status, statusText: response.statusText, headers })
      );
    }
    return response;
  } catch (err) {
    const cached = await cache.match(request);
    if (cached) return cached;
    throw err;
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Never interfere with writes or non-GET verbs — a cached PUT /preferences
  // would silently drop a user's persona change.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Firebase auth/identity must always hit the network; a cached token response
  // is both useless and a security foot-gun.
  if (url.hostname.endsWith("googleapis.com") || url.hostname.endsWith("firebaseapp.com")) return;

  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          if (response && response.ok) {
            const cache = await caches.open(SHELL_CACHE);
            cache.put(request, response.clone());
          }
          return response;
        } catch {
          const cache = await caches.open(SHELL_CACHE);
          const cached = await cache.match(request);
          if (cached) return cached;
          const offline = await cache.match(OFFLINE_URL);
          if (offline) return offline;
          return new Response("Offline", { status: 503, statusText: "Offline" });
        }
      })()
    );
    return;
  }

  if (isImmutableAsset(url)) {
    event.respondWith(cacheFirst(request, STATIC_CACHE).catch(() => fetch(request)));
    return;
  }

  if (isDataRequest(url) || isBackendRequest(url)) {
    event.respondWith(networkFirstWithTimestamp(request, DATA_CACHE));
    return;
  }
});

// ---------------------------------------------------------------------------
// Web Push — P0 severe weather warnings.
//
// The backend's warning job posts a payload shaped like:
//   { title, body, severity, type, url, tag }
// `severity` drives requireInteraction: a red/orange IMD warning should stay on
// screen until acknowledged rather than auto-dismissing while the user sleeps.
// ---------------------------------------------------------------------------

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { body: event.data ? event.data.text() : "" };
  }

  const title = payload.title || "Mausam severe weather warning";
  const severity = (payload.severity || "").toLowerCase();
  const isHighSeverity = severity === "red" || severity === "orange" || severity === "severe";

  event.waitUntil(
    self.registration.showNotification(title, {
      body: payload.body || "",
      icon: "/icon-192x192.png",
      badge: "/icon-192x192.png",
      // Collapse repeat pushes about the same warning instead of stacking them.
      tag: payload.tag || "mausam-severe-warning",
      renotify: true,
      requireInteraction: isHighSeverity,
      vibrate: isHighSeverity ? [200, 100, 200, 100, 200] : [100],
      data: { url: payload.url || "/home" },
    })
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = event.notification.data?.url || "/home";

  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      // Reuse an existing tab when one is open, rather than piling up windows.
      for (const client of clientList) {
        if ("focus" in client) {
          await client.focus();
          if ("navigate" in client) await client.navigate(target).catch(() => {});
          return;
        }
      }
      if (self.clients.openWindow) await self.clients.openWindow(target);
    })()
  );
});

/**
 * Chrome can rotate a subscription without user action. When it does, the old
 * endpoint stops working, so tell the page to re-register with the backend.
 */
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      clientList.forEach((client) => client.postMessage({ type: "PUSH_SUBSCRIPTION_CHANGED" }));
    })()
  );
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
});
